CREATE TABLE "RateLimitBucket" ("id" uuid PRIMARY KEY, "scope" varchar(80) NOT NULL, "subjectHash" varchar(128) NOT NULL, "windowStart" timestamptz NOT NULL, "count" integer NOT NULL DEFAULT 0, "expiresAt" timestamptz NOT NULL, UNIQUE("scope", "subjectHash", "windowStart"));
CREATE TABLE "IdempotencyReceipt" ("id" uuid PRIMARY KEY, "userId" uuid NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT, "authSessionId" uuid NOT NULL REFERENCES "AuthenticationSession"("id") ON DELETE RESTRICT, "operation" varchar(100) NOT NULL, "key" uuid NOT NULL, "payloadHash" varchar(128) NOT NULL, "resourceId" uuid, "createdAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("userId", "operation", "key"));
